CREATE TABLE `app_portofolio` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_kategori` int(11) NOT NULL,
  `gambar` varchar(250) NOT NULL,
  `nama` varchar(250) NOT NULL,
  `tag` varchar(250) NOT NULL,
  `kilasan` text NOT NULL,
  `start_date` year(4) NOT NULL,
  `end_date` year(4) DEFAULT NULL,
  `link` varchar(250) DEFAULT NULL,
  `id_author` varchar(36) NOT NULL,
  `flag` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `id_author` (`id_author`),
  CONSTRAINT `app_portofolio_ibfk_1` FOREIGN KEY (`id_author`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
